INSERT INTO factchecks (id, claim, truth, sources, created_at) VALUES (1, 'В социальных сетях массово распространяется видео, на котором якобы запечатлены недавние события в городе N.', 'На самом деле это видео было снято в 2018 году в совершенно другом регионе. Анализ метаданных и обратный поиск по изображениям это подтверждают.', '{"https://example.com/original-video-2018","Анализ независимых экспертов Bellingcat"}', '2026-04-03T15:49:50.131Z');
